WHERE question_id = #{questionId} AND voter_key = #{voterKey}

SELECT COUNT(*)
FROM moondap.md_balance_vote
WHERE question_id = #{questionId} AND voter_key = #{voterKey}

mapper.update:
UPDATE moondap.md_balance_vote
   SET selected_side = #{side}
 WHERE question_id = #{questionId} AND voter_key = #{voterKey}

mapper.select:
SELECT *
FROM moondap.md_balance_comment
WHERE question_id = #{id}


        ORDER BY like_count DESC, created_at DESC, no DESC


        ORDER BY created_at DESC, no DESC


LIMIT #{limit} OFFSET #{offset}

SELECT l.comment_no
FROM moondap.md_balance_comment_like l
JOIN moondap.md_balance_comment c ON c.no = l.comment_no
WHERE c.question_id = #{questionId}
  AND l.voter_key = #{voterKey}

mapper.update:
UPDATE moondap.md_balance_comment
   SET like_count = like_count + #{cnt}
WHERE no = #{no} AND question_id = #{id}

UPDATE moondap.md_balance_game
   SET title = #{title}
      ,is_spicy = #{isSpicy}
      ,category = #{category}
      ,status = #{status}
      ,option_1_text = #{option1Text}
      ,option_1_image_path = #{option1ImagePath}
      ,option_2_text = #{option2Text}
      ,option_2_image_path = #{option2ImagePath}
WHERE id = #{id}
